      body: "A região apresenta um clima de transição entre agreste e sertão, com médias térmicas elevadas e precipitação concentrada em poucos meses. A estação chuvosa ocorre durante parte do primeiro semestre, enquanto o restante do ano tende a ser seco. Esses padrões são típicos do interior nordestino e afetam ciclos produtivos e sociais.",
